'use strict';
// Full editorial tour pages are rendered from the same catalogue exported as JSON/Markdown.
function tourMarkdown(t){
 const bullets=xs=>xs.map(x=>'- '+x).join('\n');
 return `# ${t.code} — ${t.name}\n\n${t.summary}\n\n${t.description}\n\n## Thông tin nhanh\n\n- Trạng thái: ${t.statusLabel}\n- Thời lượng: ${t.days} ngày ${t.nights} đêm\n- Tuyến: ${t.places.join(' → ')}\n- Phong cách: ${t.tags.join(', ')}\n- Giá dự kiến: ${money(t.price)} – ${money(t.priceMax)}/người lớn\n- Điểm đón/trả: ${t.departure}\n- Lịch khởi hành: ${t.departureSchedule}\n- Quy mô: ${t.group}\n- Phù hợp: ${t.audience}\n- Mức vận động: ${t.difficulty}\n- Thời điểm: ${t.season}\n- Di chuyển: ${t.transport}\n\n${t.pricingNote}\n\n${t.timingNote}\n\n## Điểm nhấn\n\n${bullets(t.highlights)}\n\n## Lịch trình\n\n${t.itinerary.map(d=>`### Ngày ${d.day}: ${d.title}\n\nĂn: ${d.meals.join(', ')}. Nghỉ: ${d.stay}.\n\n${d.activities.map(a=>`- **${a.time} · ${a.title}:** ${a.description}`).join('\n\n')}`).join('\n\n')}\n\n## Ăn uống và lưu trú\n\n${t.food}\n\n${t.lodging}\n\n## Dự kiến bao gồm\n\n${bullets(t.included)}\n\n## Không bao gồm\n\n${bullets(t.excluded)}\n\n## Chuẩn bị\n\n${bullets(t.packing)}\n\n## Lưu ý riêng\n\n${bullets(t.notes)}\n\n## Phương án thời tiết\n\n${t.weatherPlan}\n\n## Trẻ em, đặt chỗ và bảo hiểm\n\n${t.children}\n\n${t.cancellation}\n\n${t.insurance}\n\n## Điều kiện trước khi mở bán\n\n${bullets(t.operationChecklist)}\n\n## Nguồn đối chiếu điểm đến\n\n${t.sourceIds.map(id=>`- [${TRA_CATALOG.sources[id].title}](${TRA_CATALOG.sources[id].url})`).join('\n')}\n\n${TRA_CATALOG.editorialNote}\n`;
}
function tourDetailsHTML(t){
 const esc=escapeHTML, list=xs=>'<ul>'+xs.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';
 const directions='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent('Trung tâm Thái Nguyên Việt Nam')+'&destination='+encodeURIComponent('Trung tâm Thái Nguyên Việt Nam')+'&waypoints='+encodeURIComponent(t.places.map(p=>p+' Thái Nguyên Việt Nam').join('|'))+'&travelmode=driving';
 return `<article class="tour-details"><img src="assets/${t.image}" alt="${esc(t.imageCaption)}"><p class="micro">${esc(t.imageCaption)}</p><p class="eyebrow">${t.code} · ${t.days} NGÀY ${t.nights? t.nights+' ĐÊM':''} · ${esc(t.label)}</p><h2>${esc(t.name)}</h2><p class="tour-lead">${esc(t.summary)}</p><div class="tour-route">${t.places.map(p=>esc(p)).join(' <span>→</span> ')}</div><p>${esc(t.description)}</p><div class="detail-facts"><div><small>GIÁ DỰ KIẾN / NGƯỜI LỚN</small><b>${money(t.price)} – ${money(t.priceMax)}</b></div><div><small>QUY MÔ ĐOÀN</small><b>${esc(t.group)}</b></div></div><p class="editorial-status">${esc(t.statusLabel)} · Chưa có đánh giá</p><p class="micro">${esc(t.pricingNote)}</p><div class="detail-actions"><button class="button" id="book-demo">Tạo phiếu dự toán mẫu ↗</button><button class="outline" id="download-tour">Tải lịch trình .md</button><a class="outline" href="${directions}" target="_blank" rel="noopener">Tra tuyến di chuyển ↗</a></div><p class="micro">Liên kết bản đồ chỉ hỗ trợ tra tuyến theo tên địa điểm, chưa phải tuyến khảo sát; một số thiết bị giới hạn số điểm trung gian.</p><h3>Điều khiến chuyến đi đáng nhớ</h3>${list(t.highlights)}<div class="detail-overview"><h3>Chuyến đi này dành cho ai?</h3><p>${esc(t.audience)}</p><p><b>Mức vận động:</b> ${esc(t.difficulty)}</p><p><b>Thời điểm gợi ý:</b> ${esc(t.season)}</p><p><b>Đón và trả khách:</b> ${esc(t.departure)}</p><p><b>Khởi hành:</b> ${esc(t.departureSchedule)}</p><p><b>Di chuyển:</b> ${esc(t.transport)}</p></div><h3>Lịch trình chi tiết</h3><p class="micro">${esc(t.timingNote)}</p><div class="itinerary">${t.itinerary.map(d=>`<section class="itinerary-day"><div class="day-header"><span>${String(d.day).padStart(2,'0')}</span><div><h4>Ngày ${d.day} · ${esc(d.title)}</h4><small>Ăn: ${d.meals.map(esc).join(' · ')}<br>Nghỉ: ${esc(d.stay)}</small></div></div><ol>${d.activities.map(a=>`<li><time>${esc(a.time)}</time><div><h5>${esc(a.title)}</h5><p>${esc(a.description)}</p></div></li>`).join('')}</ol></section>`).join('')}</div><h3>Ăn uống & lưu trú</h3><p>${esc(t.food)}</p><p>${esc(t.lodging)}</p><div class="service-columns"><section><h3>Dự kiến bao gồm</h3>${list(t.included)}</section><section><h3>Không bao gồm</h3>${list(t.excluded)}</section></div><h3>Trước khi lên đường</h3>${list(t.packing)}<h3>Lưu ý của hành trình</h3>${list(t.notes)}<div class="weather-plan"><h3>Nếu thời tiết thay đổi</h3><p>${esc(t.weatherPlan)}</p></div><details><summary>Trẻ em, đặt chỗ và bảo hiểm</summary><p>${esc(t.children)}</p><p>${esc(t.cancellation)}</p><p>${esc(t.insurance)}</p></details><details><summary>Nguồn tham khảo & trạng thái biên tập</summary><p>${esc(TRA_CATALOG.editorialNote)}</p><p>${esc(t.geographyNote)}</p><ul>${t.sourceIds.map(id=>`<li><a href="${TRA_CATALOG.sources[id].url}" target="_blank" rel="noopener">${esc(TRA_CATALOG.sources[id].title)} ↗</a></li>`).join('')}</ul><p>Cập nhật nội dung: 14/10/2026.</p><h4>Việc cần xác nhận trước khi mở bán</h4>${list(t.operationChecklist)}</details></article>`;
}
openTour=function(id){const t=tours.find(t=>t.id===id);if(!t){toast('Không tìm thấy tour.');return;}showModal(tourDetailsHTML(t));$('#modal').scrollTop=0;$('#book-demo').onclick=()=>booking(t);$('#download-tour').onclick=()=>download(t.slug+'.md',tourMarkdown(t));};
// Filter options come from the complete catalogue; personal trip planning is unchanged.
$('#destination').innerHTML='<option value="">Tất cả điểm đến</option>'+TRA_CATALOG.places.map(p=>`<option>${escapeHTML(p.name)}</option>`).join('');
$('#duration').innerHTML='<option value="">Bao nhiêu ngày cũng được</option>'+[1,2,3,4,5].map(d=>`<option value="${d}">${d} ngày${d>1?' '+(d-1)+' đêm':''}</option>`).join('');
$('#price').innerHTML='<option value="">Tất cả mức giá</option><option value="1000000">Đến 1 triệu</option><option value="3000000">Đến 3 triệu</option><option value="5000000">Đến 5 triệu</option><option value="8000000">Đến 8 triệu</option>';
$('#tags').innerHTML=['','Thiên nhiên','Văn hóa','Nghỉ dưỡng','Gia đình','Khám phá','Trekking','Nhiếp ảnh'].map(tag=>`<button class="chip ${tag?'':'selected'}" data-tag="${tag}">${tag||'Tất cả'}</button>`).join('');
renderTours();
if(/^#tour-\d+$/.test(location.hash))openTour(Number(location.hash.slice(6)));
